code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v), 0)
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); pts=[]
            while q:
                y,x=q.pop(); pts.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        z=(y+dy,x+dx)
                        if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]==color:
                            seen.add(z); q.append(z)
            comps.append(pts)
    # The answer is one of the separate motifs; choose the unusually tall motif.
    pts=max(comps,key=lambda p: (max(y for y,x in p)-min(y for y,x in p), len(p)))
    y0=min(y for y,x in pts); y1=max(y for y,x in pts); x0=min(x for y,x in pts); x1=max(x for y,x in pts)
    return [[grid[y][x] if (y,x) in set(pts) else 0 for x in range(x0,x1+1)] for y in range(y0,y1+1)]
